#!/usr/bin/env node
// BUILD A SINGLE-FILE `pilot-chat` FOR A `--use-api` DEPLOY (no Docker).
//
// WHY: `supabase functions deploy pilot-chat --use-api` uploads every local
// module in the function's graph — 284 files, ~5.7 MB of heavily commented
// source — and the API answers HTTP 413 (request entity too large). Bundling
// the LOCAL modules into one file (comments dropped, unused code tree-shaken)
// makes the upload ~1.4 MB. Behaviour is unchanged: the same modules, in the
// same ESM evaluation order. Remote imports (`https://esm.sh/...`) and
// `node:*` built-ins stay external and are resolved by Supabase as before.
// Not minified, so stack traces stay readable.
//
//   node scripts/test-project/build-pilot-chat-bundle.mjs <out-dir>
//
// Writes <out-dir>/supabase/functions/pilot-chat/index.ts (the bundle) and a
// minimal <out-dir>/supabase/config.toml naming ONLY the TEST project, so the
// CLI run with `--workdir <out-dir>` can resolve nothing else.
import { build } from "esbuild";
import { mkdirSync, writeFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { execFileSync } from "node:child_process";

//   node scripts/test-project/build-pilot-chat-bundle.mjs <out-dir> [function] [test|production]
// Defaults: pilot-chat, test. The production target names ONLY the production
// project in the generated config.toml and is used by scripts/release/.
const REFS = { test: "tlvnfrxzjhsjgdofwehb", production: "ohsdatpvfdjdemstoiuj" };
const out = process.argv[2];
const fn = process.argv[3] ?? "pilot-chat";
const target = process.argv[4] ?? "test";
if (!out || !/^[a-z0-9-]+$/.test(fn) || !(target in REFS)) {
  console.error("usage: build-pilot-chat-bundle.mjs <out-dir> [function] [test|production]"); process.exit(2);
}
const TEST_REF = REFS[target];
const fnDir = join(resolve(out), "supabase", "functions", fn);
mkdirSync(fnDir, { recursive: true });
const entry = join(fnDir, "index.ts");

// THE BUILD STAMP. `_shared/buildStamp.generated.ts` normally says
// "unstamped"; the bundle carries the real commit so the deployed function's
// `x-agentory-build` header names it. A dirty tree is marked, never hidden.
const git = (...a) => execFileSync("git", a, { encoding: "utf8" }).trim();
const sha = git("rev-parse", "HEAD");
const dirty = git("status", "--porcelain", "--untracked-files=no").length > 0;
const stamp = { sha: dirty ? `${sha}-dirty` : sha, built_at: new Date().toISOString().replace(/\.\d{3}Z$/, "Z") };
const stampPlugin = {
  name: "build-stamp",
  setup(b) {
    b.onLoad({ filter: /buildStamp\.generated\.ts$/ }, () => ({
      contents: `export const BUILD = ${JSON.stringify(stamp)} as const;\n`, loader: "ts",
    }));
  },
};

const res = await build({
  plugins: [stampPlugin],
  entryPoints: [`supabase/functions/${fn}/index.ts`],
  bundle: true, format: "esm", platform: "neutral", target: "es2022",
  external: ["https://*", "http://*", "node:*", "npm:*", "jsr:*"],
  legalComments: "none", outfile: entry, metafile: true, logLevel: "warning",
  banner: { js: `// GENERATED by scripts/test-project/build-pilot-chat-bundle.mjs from supabase/functions/${fn}/index.ts @ ${stamp.sha}. Do not edit.` },
});
const externals = new Set();
for (const o of Object.values(res.metafile.outputs)) for (const i of o.imports ?? []) if (i.external) externals.add(i.path);
writeFileSync(join(resolve(out), "supabase", "config.toml"),
  `# GENERATED for a ${target.toUpperCase()}-only bundled deploy of ${fn}.\nproject_id = "${TEST_REF}"\n\n[functions.${fn}]\nverify_jwt = true\n`);
const inputs = Object.keys(res.metafile.inputs).length;
console.log(JSON.stringify({
  function: fn, target, project_ref: TEST_REF, entry, bytes: statSync(entry).size, local_modules_bundled: inputs, externals: [...externals].sort(), build: stamp,
}));
